mapper.insert:

	SELECT CMS_BOARD_FILE_IDX_SEQ.NEXTVAL FROM DUAL

INSERT INTO CMS_BOARD_FILE
(
	board_idx, file_idx, real_file_name, file_name, file_ext_name,
	file_size, add_date
) VALUES
(
	#{board_idx}, #{file_idx}, #{FILE_NAME}, #{REAL_FILE_NAME}, #{FILE_EXT},
	#{FILE_SIZE}, #{FILE_ADD_DATE}
)

mapper.select:
SELECT BB_Code as board_seq, BB_Board as manage_idx, BB_Head as group_seq, BB_Parent as parent_seq, BB_Depth as group_step, ifnull(BB_ID, 'admin') as user_id, if(BB_Category = '0', '', concat('00',BB_category)) as category1,
BB_Name as user_name, BB_Pass as user_password, BB_Email as user_email, BB_Link1 as imsi_v_1, BB_Homepage as user_homepage, BB_Subject as title, BB_Content as content, if(BB_Notice = '1', 'Y', 'N') as NOTICE_YN, if(BB_Secret = '1', 'Y', 'N') as secret_yn, if(BB_OPEN = '1', 'Y', 'N') as delete_yn, BB_Hit as VIEW_COUNT, BB_WIP as user_ip, BB_MDate as modify_date, BB_WDate as add_date, BB_FileName as preview_img FROM wdb_board WHERE BB_Board = #{manager_seq}
ORDER BY BB_Code

